import data.glitch_lib

# Set of suspicious comment markers indicating documentation debt
suspicious_markers := {"TODO", "FIXME", "HACK", "BUG", "XXX", "NOTE", "WARNING", "LATER", "TEMP", "TEMPORARY", "INTERIM", "PLACEHOLDER", "MAYBE", "REVIEW", "VERIFY", "CHECK", "TESTME", "BROKEN", "UNSAFE", "INSECURE", "VULNERABLE", "WORKAROUND", "SKIP_VALIDATION", "DISABLE_VERIFY", "BYPASS", "DEBUG_MODE", "NOT_FOR_PROD", "DEV_ONLY", "LOCAL_TESTING", "DEMO_MODE"}

# Security-sensitive field names that indicate security-critical configuration
security_sensitive_fields := {"permissions", "policies", "roles", "bindings", "access_level", "scope", "security_group_rules", "firewall_rules", "ingress", "egress", "cidr_blocks", "port_ranges", "encryption_at_rest", "encryption_in_transit", "kms_key", "tls_version", "certificate", "password", "secret", "token", "api_key", "client_certificate", "mfa_enabled", "audit_logging", "log_retention", "monitoring_enabled", "alert_thresholds", "backup_enabled", "snapshot_retention", "recovery_point_objective", "description", "notes", "metadata"}

# Check if a comment contains any suspicious marker
has_suspicious_marker(content) {
    marker := suspicious_markers[_]
    regex.match(sprintf("(?i).*%s.*", [marker]), content)
}

# Extract string value from various types for analysis
get_string_value(val) = result {
    val.ir_type == "String"
    result := val.value
} else = result {
    val.ir_type == "VariableReference"
    result := val.value
} else = "" {
    true
}

# Check if a string contains suspicious keywords indicating temporary/incomplete status
has_uncertainty_language(content) {
    regex.match("(?i).*(temporary|temp|for now|until|quick fix|needs review|incomplete|not implemented|placeholder|coming soon|to be confirmed|tbd|tbc).*", content)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check direct comments in the unit block
    comment := parent.comments[_]
    has_suspicious_marker(comment.content)

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Suspicious comment indicating incomplete implementation or known issue in infrastructure code. (CWE-546)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check attributes that may contain documentation with suspicious markers
    node := parent.atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check if attribute name is security-sensitive
    security_sensitive_fields[_] == attr.name

    # Check for suspicious content in string attributes
    str_val := get_string_value(attr.value)
    str_val != ""
    has_suspicious_marker(str_val)

    result := {
        "type": "sec_susp_comm",
        "element": attr,
        "path": parent.path,
        "description": "Suspicious marker found in security-sensitive configuration field indicating documentation debt. (CWE-546)"
