package glitch

import data.glitch_lib

# Suspicious markers indicating documentation debt or incomplete implementation
suspicious_markers := {"TODO", "FIXME", "HACK", "XXX", "BUG", "WARNING", "NOTE"}

# Extended markers with word boundary checking
extended_markers := {"TEMP", "TEMPORARY", "INTERIM", "PLACEHOLDER", "LATER", "MAYBE", "REVIEW", "VERIFY", "CHECK", "TESTME", "BROKEN", "UNSAFE", "INSECURE", "VULNERABLE", "WORKAROUND", "BYPASS", "SKIP", "DISABLE", "DEBUG", "DEV_ONLY", "LOCAL_TESTING", "DEMO_MODE", "NOT_FOR_PROD", "HOTFIX", "KLUDGE", "DEPRECATED", "OBSOLETE", "REMOVE", "DELETE", "CLEANUP", "REFACTOR"}

# Uncertainty and fragility patterns
uncertainty_patterns := ["for now", "needs review", "incomplete", "not implemented", "not yet", "placeholder", "coming soon", "to be", "tbd", "temporary", "quick fix", "hardcoded", "hard coded", "hard code", "cannot change", "will break", "doing so will", "currently", "at the moment", "right now", "only for", "just for", "limited to", "restricted to"]

# Issue tracker URL indicators
tracker_indicators := {"issues", "issue", "tracker", "bug", "ticket", "jira", "github", "gitlab", "bitbucket", "bugzilla", "phabricator", "trello"}

# Check for suspicious marker in content
has_suspicious_marker(content) {
    marker := suspicious_markers[_]
    regex.match(sprintf("(?i)\\b%s\\b", [marker]), content)
}

has_suspicious_marker(content) {
    marker := extended_markers[_]
    regex.match(sprintf("(?i)\\b%s\\b", [marker]), content)
}

# Check for uncertainty/fragility language
has_uncertainty_language(content) {
    pattern := uncertainty_patterns[_]
    regex.match(sprintf("(?i)%s", [pattern]), content)
}

# Check for issue tracker URLs
has_tracker_url(content) {
    indicator := tracker_indicators[_]
    regex.match(sprintf("(?i)%s", [indicator]), content)
    regex.match("(?i)(https?://|www\\.)", content)
}

# Clean comment content
clean_comment(content) = clean {
    clean := regex.replace(content, "^\\s*[#/\\*!;-]+\\s*", "")
}

# Collect all comments from unit block and nested blocks
all_comments(block) = comments {
    direct := {c | c := block.comments[_]}
    nested := {c | nested := block.unit_blocks[_]; c := nested.comments[_]}
    comments := direct | nested
}

# Main detection: suspicious markers in comments
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    comment := all_comments(parent)[_]
    clean := clean_comment(comment.content)

    has_suspicious_marker(clean)

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Suspicious comment indicating incomplete implementation or known issue in infrastructure code. (CWE-546)"
    }
}

# Detection: uncertainty/fragility language in comments
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    comment := all_comments(parent)[_]
    clean := clean_comment(comment.content)

    has_uncertainty_language(clean)

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Comment indicates fragile, temporary, or incomplete implementation that may compromise infrastructure security. (CWE-546)"
    }
}

# Detection: issue tracker references
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    comment := all_comments(parent)[_]

    has_tracker_url(comment.content)

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Comment references external issue tracker indicating known bug or unresolved issue. (CWE-546)"
    }
}

